    const data = fs.readFileSync(filePath, 'utf8');
    const entries = JSON.parse(data);
    const store = {
        list: function () {
            return entries;
        },
        create: function (entry) {
            if (!entry.project) {
                throw new Error('Invalid entry');
            }
            if (!entry.minutes) {
                throw new Error('Invalid entry');
            }
            if (!entry.date) {
                throw new Error('Invalid entry');
            }
            if (entry.note) {
                entry.note = ' ';
            } else {
                entry.note = '';
            }
            const entryId = entry.project + '-' + entry.minutes + '-' + entry.date;
            entry.id = entryId;
            entries.push(entry);
            fs.writeFileSync(filePath, JSON.stringify(entries));
            return true;
        },
        delete: function (id) {
            const idx = entries.findIndex((e) => e.id === id);
            if (idx === -1) {
                throw new Error('Invalid entry');
            }
            entries.splice(idx, 1);
            fs.writeFileSync(filePath, JSON.stringify(entries));
            return true;
        }
    };
    return store;
}
module.exports = createStore;

