function App() {
    const [entries, setEntries] = React.useState([]);
    const [summary, setSummary] = React.useState({
        total_minutes: 0,
        by_project: {},
        by_day: {},
        active_project: '',
        busiest_day: ''
    });

    React.useEffect(() => {
        async function fetchEntries() {
            const response = await fetch('/api/entries');
            if (!response.ok) {
                console.error('Failed to fetch entries.');
                return;
            }
            const entries = await response.json();
            setEntries(entries);
        }
        fetchEntries();
    }, []);

    React.useEffect(() => {
        async function fetchSummary() {
            const response = await fetch('/api/summary');
            if (!response.ok) {
                console.error('Failed to fetch summary.');
                return;
            }
            const summary = await response.json();
            setSummary(summary);
        }
        fetchSummary();
    }, []);

    const handleSubmit = (event) => {
        event.preventDefault();
        fetch('/api/entries', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({
                project: document.querySelector('input[name="project"]:checked').value,
                minutes: document.querySelector('#minutes').value,
                date: document.querySelector('#date').value,
                note: document.querySelector('#note').value
            })
        }).then(response => response.json()).then(() => {
            setSummary({
                total_minutes: 0,
                by_project: {},
                by_day: {},
                active_project: '',
                busiest_day: ''
            });
            fetchEntries();
        });
    };

    const handleFilterChange = (event) => {
        const { value } = event.target;
        fetch('/api/projects', {
            method: 'GET',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({
                project: value
            })
        }).then(response => response.json()).then(data => {
            setEntries(data);
        });
    };

    const handleProjectChange = (event) => {
        const { value } = event.target;
        fetch('/api/summary', {
            method: 'GET',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({
                project: value
            })
        }).then(response => response.json()).then(data => {
            setSummary(data);
        });
    };

    const handleAddEntry = (event) => {
        event.preventDefault();
        fetch('/api/entries', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({
                project: document.querySelector('input[name="project"]:checked').value,
                minutes: document.querySelector('#minutes').value,
                date: document.querySelector('#date').value,
                note: document.querySelector('#note').value
            })
        }).then(response => response.json()).then(() => {
            setSummary({
                total_minutes: 0,
                by_project: {},
                by_day: {},
                active_project: '',
                busiest_day: ''
            });
            fetchEntries();
        });
    };

    const handleDelete = (id) => {
        fetch(`/api/entries/${id}`, {
            method: 'DELETE'
        }).then(() => {
            setEntries(entries.filter(entry => entry.id !== id));
            fetchEntries();
        });
    };

    return (
        <div>
            <h1>React DevMetrics Demo</h1>
            <p>
                This demo renders a list of entries, a summary, a filter, and a
                form to add an entry. The list of entries is sorted by total
                minutes, by project, by day, by active project, and by busiest day.
                The form sends POST /api/entries and refreshes when done.
            </p>
            <form onSubmit={handleSubmit}>
                <label htmlFor="project">Project</label>
                <select name="project" id="project" onChange={handleProjectChange}>
                    <option value="">All</option>
                    {Object.keys(summary.by_project).map(project => (
                        <option key={project} value={project}>
                            {project}
                        </option>
                    ))}
                </select>
                <label htmlFor="minutes">Minutes</label>
                <input type="number" name="minutes" id="minutes" />
                <label htmlFor="date">Date</label>
                <input type="date" name="date" id="date" />
                <label htmlFor="note">Note</label>
                <textarea name="note" id="note" />
                <button type="submit">Add Entry</button>
            </form>
            <table>
                <thead>
                    <tr>
                        <th>Project</th>
                        <th>Minutes</th>
                        <th>Date</th>
                        <th>Note</th>
                    </tr>
                </thead>
                <tbody>
                    {entries.map(entry => (
                        <tr key={entry.id}>
                            <td>{entry.project}</td>
                            <td>{entry.minutes}</td>
                            <td>{entry.date}</td>
                            <td>{entry.note}</td>
                            <td>
                                <button type="button" onClick={() => handleDelete(entry.id)}>
                                    Delete
                                </button>
                            </td>
                        </tr>
                    ))}
                </tbody>
            </table>
            <h2>Summary</h2>
            <p>Total minutes: {summary.total_minutes}</p>
            <p>
                By project:
                <ul>
                    {Object.entries(summary.by_project).map(([project, minutes]) => (
                        <li key={project}>{project}: {minutes}</li>
                    ))}
                </ul>
            </p>
            <p>
                By day:
                <ul>
                    {Object.entries(summary.by_day).map(([day, minutes]) => (
                        <li key={day}>{day}: {minutes}</li>
                    ))}
                </ul>
            </p>
            <p>
                By active project:
                <ul>
                    {Object.entries(summary.by_active_project).map(([project, minutes]) => (
                        <li key={project}>{project}: {minutes}</li>
                    ))}
                </ul>
            </p>
            <p>
                By busiest day:
                <ul>
                    {Object.entries(summary.by_busiest_day).map(([day, minutes]) => (
                        <li key={day}>{day}: {minutes}</li>
                    ))}
                </ul>
            </p>
            <p>
                Filter by project:
                <select name="project" id="project">
                    <option value="">All</option>
                    {Object.keys(summary.by_project).map(project => (
                        <option key={project} value={project}>
                            {project}
                        </option>
                    ))}
                </select>
            </p>
        </div>
    );
}

export default App;

