const fs = require('node:fs');
function createStore(filePath) {
  let store = {
    entries: [],
    save: (filePath, data) => {
      fs.writeFile(filePath, JSON.stringify(data), (err) => {
        if (err) throw err;
        console.log('File saved');
      });
    },
    list: () => {
      return store.entries;
    },
    create: (entry) => {
      const newEntry = Object.assign(entry, { id: Math.random().toString() });
      if (!entry.project || !entry.minutes || !entry.date) {
        throw new Error('Invalid entry');
      }
      if (entry.date.length !== 10 || entry.date[4] !== '-' || entry.date[7] !== '-') {
        throw new Error('Invalid entry');
      }
      if (newEntry.project.length > 20) {
        throw new Error('Invalid entry');
      }
      if (newEntry.minutes < 0 || newEntry.minutes > 500) {
        throw new Error('Invalid entry');
      }
      const date = new Date(entry.date);
      if (date.toString() === 'Invalid Date') {
        throw new Error('Invalid entry');
      }
      store.entries.push(newEntry);
      store.save(filePath, store.entries);
      return newEntry;
    },
    delete: (id) => {
      const index = store.entries.findIndex((entry) => entry.id === id);
      if (index === -1) {
        throw new Error('Entry not found');
      }
      store.entries.splice(index, 1);
      store.save(filePath, store.entries);
      return true;
    },
  };
  return store;
}

