  setLoading(true);
  try {
    const entries = await fetch('/api/entries').then(res => res.json());
    const filteredEntries = filterEntries(entries, filter);
    setEntries(filteredEntries);
    setSummary(getSummary(entries));
    setOffline(false);
  } catch (err) {
    setOffline(true);
    setError(err.message);
  } finally {
    setLoading(false);
  }
