const express = require('express');
function createApp(store, processor) {
  const app = express();
  app.use(express.json());
  app.use(function (req, res, next) {
    res.header('Access-Control-Allow-Origin', '*');
    res.header('Access-Control-Allow-Headers', 'Origin, X-Requested-With, Content-Type, Accept');
    next();
  });
  app.get('/health', function (req, res) {
    res.send({ ok: true });
  });
  app.get('/api/entries', function (req, res) {
    res.send(store.list());
  });
  app.post('/api/entries', function (req, res) {
    const entry = req.body;
    if (!entry.project || !entry.minutes || !entry.date) {
      res.send({ error: 'Invalid entry' });
    } else {
      res.send({ item: processor({ entries: store.create(entry) }) });
    }
  });
  app.delete('/api/entries/:id', function (req, res) {
    const id = req.params.id;
    if (!store.delete(id)) {
      res.send({ deleted: false });
    } else {
      res.send({ deleted: true });
    }
  });
  app.get('/api/projects', function (req, res) {
    res.send(Array.from(new Set(store.list())));
  });
  app.get('/api/summary', function (req, res) {
    res.send(processor({ entries: store.list() }));
  });
  return app;
}

