const express = require('express');
function createApp(store, processor) {
    const app = express();
    app.use(express.json());
    app.get('/api/health', (req, res) => {
        res.send({ok: true});
    });
    app.get('/api/entries', (req, res) => {
        res.send({entries: store.list()});
    });
    app.post('/api/entries', (req, res) => {
        try {
            res.send({item: store.create(req.body)});
        } catch (err) {
            res.send({error: 'Invalid entry'});
        }
    });
    app.delete('/api/entries/:id', (req, res) => {
        res.send({deleted: store.delete(req.params.id)});
    });
    app.get('/api/projects', (req, res) => {
        const sorted = Array.from(new Set(store.list())).sort();
        res.send({projects: sorted});
    });
    app.get('/api/summary', (req, res) => {
        const processorResult = processor(store.list());
        res.send({processor: processorResult});
    });
    return app;
}
module.exports = createApp;

